-- Import 50 European and Swiss recipes. Requires schema.sql and recipe-categories.sql.
-- Safe to rerun: recipes whose titles already exist are skipped.
begin;
do $import_recipes$
declare
  item jsonb;
  ingredient jsonb;
  step_row record;
  recipe_id uuid;
  category_id uuid;
  imported_count integer := 0;
  skipped_count integer := 0;
begin
  for item in select value from jsonb_array_elements($recipe_data$[
    {"title":"Rösti","category":"Schweizer Küche","description":"Knusprige Schweizer Kartoffelrösti als Hauptgericht oder Beilage.","ingredients":[[800,"g","festkochende Kartoffeln"],[2,"EL","Butter oder Bratbutter"],[1,"TL","Salz"],[1,"Prise","Pfeffer"]],"steps":["Kartoffeln in der Schale knapp weich kochen, auskühlen lassen und schälen. Grob raffeln und salzen.","Butter in einer Pfanne erhitzen, Kartoffeln hineingeben und zu einem Kuchen formen. Bei mittlerer Hitze goldbraun braten, wenden und die zweite Seite ebenfalls knusprig braten."]},
    {"title":"Zürcher Geschnetzeltes","category":"Schweizer Küche","description":"Kalbsgeschnetzeltes in Rahmsauce mit Champignons, klassisch zu Rösti.","ingredients":[[500,"g","geschnetzeltes Kalbfleisch"],[200,"g","Champignons"],[1,"","Zwiebel"],[150,"ml","Rahm"],[100,"ml","Weisswein"],[1,"EL","Butter"]],"steps":["Fleisch portionsweise in heisser Butter kurz anbraten, würzen und warm stellen. Zwiebel und Champignons in derselben Pfanne anbraten.","Mit Weisswein ablöschen und etwas einkochen lassen. Rahm zugeben, cremig köcheln, Fleisch samt Saft kurz darin erwärmen und abschmecken."]},
    {"title":"Älplermagronen","category":"Schweizer Küche","description":"Herzhafte Magronen mit Kartoffeln, Rahm, Käse und Röstzwiebeln.","ingredients":[[300,"g","Pasta-Magronen"],[300,"g","Kartoffeln"],[150,"g","geriebener Gruyère"],[150,"ml","Rahm"],[2,"","Zwiebeln"],[1,"EL","Butter"]],"steps":["Kartoffeln würfeln und in Salzwasser knapp weich kochen. Magronen beigeben und al dente garen, dann abgiessen.","Rahm erhitzen und mit Pasta, Kartoffeln und Käse mischen. Zwiebeln in Butter goldbraun rösten und darübergeben. Mit Apfelmus servieren."]},
    {"title":"Schweizer Käsefondue","category":"Schweizer Küche","description":"Geschmolzene Käsemischung mit Weisswein, Knoblauch und Brotwürfeln.","ingredients":[[400,"g","Gruyère, gerieben"],[400,"g","Vacherin Fribourgeois, gerieben"],[300,"ml","trockener Weisswein"],[1,"","Knoblauchzehe"],[1,"EL","Maisstärke"],[1,"kg","Brot in Würfeln"]],"steps":["Caquelon mit der halbierten Knoblauchzehe ausreiben. Wein erwärmen, Käse portionsweise einrühren und bei kleiner Hitze schmelzen.","Maisstärke mit wenig Wein verrühren, ins Fondue geben und unter Rühren einmal aufkochen. Auf dem Rechaud warm halten und Brot hineintunken."]},
    {"title":"Raclette mit Kartoffeln","category":"Schweizer Küche","description":"Geschmolzener Raclettekäse mit kleinen Kartoffeln und klassischen Beilagen.","ingredients":[[800,"g","Raclettekäse"],[1,"kg","kleine festkochende Kartoffeln"],[150,"g","Cornichons"],[150,"g","Silberzwiebeln"],[1,"TL","Paprika"]],"steps":["Kartoffeln in Salzwasser gar kochen und warm halten. Cornichons und Silberzwiebeln in Schälchen bereitstellen.","Käsescheiben im Racletteofen schmelzen, über die Kartoffeln geben und nach Belieben mit Paprika würzen."]},
    {"title":"Birchermüesli","category":"Schweizer Küche","description":"Schweizer Frühstücksklassiker mit Haferflocken, Apfel, Joghurt und Nüssen.","ingredients":[[120,"g","Haferflocken"],[150,"ml","Milch"],[2,"","Äpfel"],[200,"g","Naturejoghurt"],[2,"EL","gehackte Haselnüsse"],[1,"EL","Zitronensaft"]],"steps":["Haferflocken mit Milch mischen und mindestens 30 Minuten quellen lassen.","Äpfel grob raffeln und mit Zitronensaft, Joghurt und Nüssen unter die Flocken mischen."]},
    {"title":"Bündner Gerstensuppe","category":"Schweizer Küche","description":"Kräftige Suppe mit Rollgerste, Gemüse und Bündnerfleisch.","ingredients":[[100,"g","Rollgerste"],[150,"g","Bündnerfleisch, gewürfelt"],[1,"","Karotte"],[1,"","Lauchstange"],[100,"g","Knollensellerie"],[1,"l","Gemüsebouillon"],[100,"ml","Rahm"]],"steps":["Gemüse klein würfeln. Mit Rollgerste und Bouillon aufkochen und bei kleiner Hitze etwa 45 Minuten köcheln lassen.","Bündnerfleisch beigeben und weitere 10 Minuten garen. Rahm einrühren, abschmecken und heiss servieren."]},
    {"title":"Capuns","category":"Schweizer Küche","description":"Bündner Mangoldwickel mit würzigem Teig und Rahmsauce.","ingredients":[[12,"","grosse Mangoldblätter"],[200,"g","Mehl"],[2,"","Eier"],[100,"ml","Milch"],[100,"g","Salsiz, gewürfelt"],[200,"ml","Gemüsebouillon"],[100,"ml","Rahm"]],"steps":["Mehl, Eier und Milch zu einem zähen Spätzliteig rühren und Salsizwürfel untermischen. Mangoldblätter kurz blanchieren.","Je einen Löffel Teig in ein Blatt geben und einwickeln. In Bouillon zugedeckt etwa 15 Minuten gar ziehen lassen, Rahm angiessen und kurz einkochen."]},
    {"title":"Ghackets mit Hörnli","category":"Schweizer Küche","description":"Schweizer Hackfleisch-Tomatensauce mit Hörnli und Apfelmus.","ingredients":[[400,"g","Rindshackfleisch"],[300,"g","Hörnli"],[1,"","Zwiebel"],[400,"g","gehackte Tomaten"],[200,"ml","Rinderbouillon"],[1,"EL","Öl"]],"steps":["Hörnli in Salzwasser al dente kochen. Zwiebel hacken und in Öl glasig dünsten, Hackfleisch krümelig anbraten.","Tomaten und Bouillon zugeben und 20 Minuten köcheln lassen. Mit Salz und Pfeffer abschmecken und mit Hörnli servieren."]},
    {"title":"Basler Mehlsuppe","category":"Schweizer Küche","description":"Dunkel geröstete Mehlsuppe mit Zwiebeln und Rotwein.","ingredients":[[60,"g","Mehl"],[40,"g","Butter"],[1,"","Zwiebel"],[1,"l","Rinderbouillon"],[100,"ml","Rotwein"],[50,"g","geriebener Gruyère"]],"steps":["Mehl in einem Topf ohne Fett unter Rühren dunkelbraun rösten. Butter und fein gehackte Zwiebel zugeben und kurz dünsten.","Bouillon nach und nach einrühren, damit keine Klümpchen entstehen. 30 Minuten köcheln, Rotwein beigeben und mit Käse servieren."]},
    {"title":"Tessiner Risotto","category":"Schweizer Küche","description":"Cremiges Risotto mit Weisswein, Bouillon und Parmesan nach Tessiner Art.","ingredients":[[300,"g","Risottoreis"],[1,"","Zwiebel"],[100,"ml","Weisswein"],[900,"ml","Gemüsebouillon, heiss"],[60,"g","Parmesan"],[30,"g","Butter"]],"steps":["Zwiebel fein hacken und in etwas Butter glasig dünsten. Reis zugeben und rühren, bis die Körner glasig sind. Mit Weisswein ablöschen.","Warme Bouillon schöpflöffelweise zugeben und häufig rühren, bis der Reis nach etwa 18 Minuten cremig und bissfest ist. Parmesan und Butter einrühren."]},
    {"title":"Walliser Cholera","category":"Schweizer Küche","description":"Walliser Kartoffel-Käse-Wähe mit Lauch, Äpfeln und Zwiebeln.","ingredients":[[1,"","runder Kuchenteig"],[400,"g","Kartoffeln"],[150,"g","Lauch"],[1,"","Apfel"],[150,"g","Walliser Raclettekäse"],[1,"","Zwiebel"],[100,"ml","Rahm"]],"steps":["Kartoffeln knapp weich kochen und in Scheiben schneiden. Lauch und Zwiebel dünsten, Apfel fein schneiden und Käse raffeln.","Teig in eine Form legen. Kartoffeln, Lauch, Apfel und Käse darauf verteilen, Rahm darübergiessen und bei 200 °C etwa 35 Minuten backen."]},
    {"title":"Schweizer Zopf","category":"Schweizer Küche","description":"Luftiges Zopfbrot mit goldbrauner Kruste, typisch für den Sonntagsbrunch.","ingredients":[[500,"g","Zopfmehl"],[300,"ml","Milch, lauwarm"],[60,"g","Butter, weich"],[20,"g","frische Hefe"],[1,"TL","Salz"],[1,"","Ei zum Bestreichen"]],"steps":["Hefe in Milch auflösen. Mit Mehl, Salz und Butter zu einem glatten Teig kneten und zugedeckt etwa 90 Minuten gehen lassen.","Teig halbieren, zwei Stränge rollen und zu einem Zopf flechten. Mit verquirltem Ei bestreichen und bei 200 °C etwa 35 Minuten goldbraun backen."]},
    {"title":"Schweizer Apfelwähe","category":"Schweizer Küche","description":"Einfacher Schweizer Apfelkuchen mit Guss aus Rahm und Ei.","ingredients":[[1,"","runder Kuchenteig"],[4,"","Äpfel"],[150,"ml","Rahm"],[2,"","Eier"],[2,"EL","Zucker"],[1,"TL","Zimt"]],"steps":["Teig in eine Wähenform legen und mit einer Gabel einstechen. Äpfel schälen, in Schnitze schneiden und fächerförmig darauflegen.","Rahm, Eier, Zucker und Zimt verquirlen und über die Äpfel giessen. Bei 200 °C etwa 35 Minuten backen."]},
    {"title":"Fotzelschnitten","category":"Schweizer Küche","description":"Arme Ritter aus Brot, in Ei-Milch getaucht und goldbraun gebraten.","ingredients":[[8,"Scheiben","altbackenes Brot"],[2,"","Eier"],[150,"ml","Milch"],[30,"g","Butter"],[2,"EL","Zucker"],[1,"TL","Zimt"]],"steps":["Eier und Milch verquirlen. Brotscheiben kurz darin wenden, bis sie die Flüssigkeit aufgenommen haben.","Butter in einer Pfanne erhitzen und Brotscheiben beidseitig goldbraun braten. Zucker und Zimt mischen und darüberstreuen."]},
    {"title":"Spaghetti Carbonara","category":"Italienische Küche","description":"Römische Pasta mit Ei, Pecorino, schwarzem Pfeffer und Guanciale.","ingredients":[[350,"g","Spaghetti"],[150,"g","Guanciale oder Pancetta"],[3,"","Eigelb"],[70,"g","Pecorino Romano"],[1,"TL","schwarzer Pfeffer"]],"steps":["Spaghetti in Salzwasser al dente kochen. Guanciale würfeln und in einer Pfanne knusprig braten.","Eigelb mit geriebenem Pecorino und Pfeffer verrühren. Pasta mit etwas Kochwasser zur Pfanne geben, vom Herd nehmen und Eimischung cremig unterheben."]},
    {"title":"Lasagne alla Bolognese","category":"Italienische Küche","description":"Ofenlasagne mit langsam gekochtem Ragù und Béchamelsauce.","ingredients":[[250,"g","Lasagneblätter"],[400,"g","Rindshackfleisch"],[500,"g","passierte Tomaten"],[500,"ml","Milch"],[40,"g","Butter"],[40,"g","Mehl"],[100,"g","Parmesan"]],"steps":["Hackfleisch anbraten, Tomaten zugeben und mindestens 30 Minuten köcheln. Aus Butter, Mehl und Milch eine Béchamelsauce kochen.","Lasagneblätter abwechselnd mit Ragù und Béchamel in eine Form schichten. Mit Parmesan abschliessen und bei 180 °C etwa 40 Minuten backen."]},
    {"title":"Pasta al pesto","category":"Italienische Küche","description":"Pasta mit frischem Basilikum-Pesto, Pinienkernen und Parmesan.","ingredients":[[350,"g","Pasta"],[40,"g","Basilikumblätter"],[30,"g","Pinienkerne"],[50,"g","Parmesan"],[80,"ml","Olivenöl"],[1,"","Knoblauchzehe"]],"steps":["Basilikum, Pinienkerne, Parmesan, Knoblauch und Olivenöl zu einem groben Pesto mixen. Pasta in Salzwasser al dente kochen.","Pasta abgiessen und etwas Kochwasser auffangen. Pesto mit der Pasta mischen und bei Bedarf mit Kochwasser cremig machen."]},
    {"title":"Risotto alla Milanese","category":"Italienische Küche","description":"Mailänder Safranrisotto mit Weisswein, Butter und Parmesan.","ingredients":[[300,"g","Risottoreis"],[1,"","Zwiebel"],[100,"ml","Weisswein"],[900,"ml","Hühnerbouillon, heiss"],[1,"Briefchen","Safran"],[60,"g","Parmesan"],[40,"g","Butter"]],"steps":["Zwiebel in Butter dünsten. Reis zugeben und glasig rösten, mit Weisswein ablöschen. Safran in etwas Bouillon auflösen.","Bouillon schöpflöffelweise einrühren und den Reis bissfest garen. Vom Herd nehmen, Parmesan und Butter einrühren und kurz ruhen lassen."]},
    {"title":"Pizza Margherita","category":"Italienische Küche","description":"Klassische Pizza mit Tomate, Mozzarella und Basilikum.","ingredients":[[300,"g","Pizzamehl"],[180,"ml","Wasser"],[5,"g","Trockenhefe"],[150,"g","passierte Tomaten"],[150,"g","Mozzarella"],[1,"Handvoll","Basilikum"]],"steps":["Mehl, Wasser und Hefe zu einem glatten Teig kneten und zugedeckt etwa eine Stunde gehen lassen. Ofen samt Blech auf höchster Stufe vorheizen.","Teig dünn ausziehen, mit Tomaten bestreichen und Mozzarella darauf verteilen. 8–12 Minuten sehr heiss backen und mit Basilikum belegen."]},
    {"title":"Gnocchi al pomodoro","category":"Italienische Küche","description":"Kartoffelgnocchi in einer einfachen Tomatensauce mit Parmesan.","ingredients":[[500,"g","Kartoffelgnocchi"],[400,"g","gehackte Tomaten"],[1,"","Knoblauchzehe"],[1,"EL","Olivenöl"],[40,"g","Parmesan"],[1,"Handvoll","Basilikum"]],"steps":["Knoblauch in Olivenöl kurz dünsten. Tomaten zugeben, würzen und 15 Minuten zu einer Sauce köcheln lassen.","Gnocchi in siedendem Salzwasser garen, bis sie an die Oberfläche steigen. Abgiessen, mit Sauce mischen und mit Parmesan und Basilikum servieren."]},
    {"title":"Minestrone","category":"Italienische Küche","description":"Gemüsesuppe mit Bohnen, Pasta und italienischen Kräutern.","ingredients":[[1,"","Zwiebel"],[1,"","Karotte"],[1,"","Zucchini"],[400,"g","Cannellini-Bohnen, gekocht"],[400,"g","gehackte Tomaten"],[1,"l","Gemüsebouillon"],[100,"g","kleine Pasta"]],"steps":["Zwiebel, Karotte und Zucchini würfeln und in etwas Öl anbraten. Tomaten und Bouillon zugeben und 15 Minuten köcheln.","Bohnen und Pasta beigeben und garen, bis die Pasta weich ist. Mit Salz, Pfeffer und Kräutern abschmecken."]},
    {"title":"Parmigiana di melanzane","category":"Italienische Küche","description":"Auberginenauflauf mit Tomatensauce, Mozzarella und Parmesan.","ingredients":[[2,"","Auberginen"],[500,"g","passierte Tomaten"],[200,"g","Mozzarella"],[80,"g","Parmesan"],[1,"","Knoblauchzehe"],[1,"Handvoll","Basilikum"]],"steps":["Auberginen längs in Scheiben schneiden, salzen und 20 Minuten ziehen lassen. Trocken tupfen und in einer Pfanne beidseitig braten.","Tomatensauce mit Knoblauch köcheln. Auberginen, Sauce, Mozzarella und Parmesan lagenweise schichten und bei 190 °C etwa 35 Minuten backen."]},
    {"title":"Pasta all'arrabbiata","category":"Italienische Küche","description":"Penne in würziger Tomatensauce mit Chili und Knoblauch.","ingredients":[[350,"g","Penne"],[400,"g","gehackte Tomaten"],[2,"","Knoblauchzehen"],[1,"","rote Chilischote"],[2,"EL","Olivenöl"],[40,"g","Pecorino"]],"steps":["Knoblauch und Chili fein schneiden und in Olivenöl kurz dünsten. Tomaten zugeben, salzen und 15 Minuten köcheln lassen.","Penne al dente kochen, abgiessen und mit der Sauce mischen. Mit Pecorino servieren."]},
    {"title":"Polenta mit Pilzen","category":"Italienische Küche","description":"Cremige Polenta mit gebratenen Waldpilzen und Parmesan.","ingredients":[[250,"g","Maisgriess"],[1,"l","Gemüsebouillon"],[400,"g","gemischte Pilze"],[1,"","Knoblauchzehe"],[50,"g","Parmesan"],[30,"g","Butter"]],"steps":["Bouillon aufkochen und Maisgriess unter Rühren einrieseln lassen. Bei kleiner Hitze nach Packungsangabe cremig garen, Butter und Parmesan einrühren.","Pilze putzen und in einer heissen Pfanne goldbraun braten. Knoblauch kurz mitbraten, würzen und auf der Polenta anrichten."]},
    {"title":"Quiche Lorraine","category":"Französische Küche","description":"Herzhafte Speck-Lauch-Quiche mit cremigem Eierguss.","ingredients":[[1,"","runder Kuchenteig"],[150,"g","Speckwürfel"],[1,"","Lauchstange"],[3,"","Eier"],[200,"ml","Rahm"],[100,"g","Gruyère"]],"steps":["Teig in eine Form legen und einstechen. Speck anbraten, Lauch in Ringe schneiden und kurz mitdünsten.","Eier, Rahm und Käse verrühren. Speck und Lauch auf dem Teig verteilen, Guss darübergiessen und bei 190 °C etwa 35 Minuten backen."]},
    {"title":"Ratatouille","category":"Französische Küche","description":"Provenzalischer Gemüseeintopf mit Aubergine, Zucchetti und Tomaten.","ingredients":[[1,"","Aubergine"],[1,"","Zucchetti"],[1,"","rote Peperoni"],[400,"g","Tomaten"],[1,"","Zwiebel"],[2,"EL","Olivenöl"],[1,"TL","Thymian"]],"steps":["Gemüse in Würfel schneiden. Zwiebel in Olivenöl glasig dünsten, Aubergine und Peperoni zugeben und anbraten.","Zucchetti und Tomaten beigeben, würzen und zugedeckt etwa 30 Minuten schmoren, bis das Gemüse weich ist."]},
    {"title":"Boeuf Bourguignon","category":"Französische Küche","description":"Langsam geschmortes Rindfleisch mit Rotwein, Zwiebeln und Champignons.","ingredients":[[800,"g","Rindsschulter in Würfeln"],[500,"ml","Rotwein"],[150,"g","Speckwürfel"],[200,"g","Champignons"],[2,"","Karotten"],[1,"","Zwiebel"],[300,"ml","Rinderbouillon"]],"steps":["Rindfleisch trocken tupfen und portionsweise anbraten. Speck und Gemüse im Topf anrösten, Fleisch zurückgeben und mit Rotwein und Bouillon aufgiessen.","Zugedeckt bei kleiner Hitze etwa 2½ Stunden schmoren. Champignons separat anbraten, in den letzten 20 Minuten beigeben und abschmecken."]},
    {"title":"Coq au vin","category":"Französische Küche","description":"Französisches Hähnchenragout mit Rotwein, Speck und Kräutern.","ingredients":[[1,"kg","Pouletschenkel"],[400,"ml","Rotwein"],[100,"g","Speckwürfel"],[200,"g","Champignons"],[1,"","Zwiebel"],[200,"ml","Hühnerbouillon"]],"steps":["Poulet trocken tupfen und rundherum anbraten. Speck, Zwiebel und Champignons im selben Topf anrösten.","Poulet zurückgeben, Rotwein und Bouillon angiessen und mit Kräutern würzen. Zugedeckt etwa 50 Minuten schmoren."]},
    {"title":"Gratin Dauphinois","category":"Französische Küche","description":"Französischer Kartoffelgratin mit Rahm, Knoblauch und Muskat.","ingredients":[[1,"kg","festkochende Kartoffeln"],[300,"ml","Rahm"],[200,"ml","Milch"],[1,"","Knoblauchzehe"],[1,"Prise","Muskat"],[30,"g","Butter"]],"steps":["Kartoffeln schälen und in dünne Scheiben schneiden. Auflaufform mit Knoblauch ausreiben und buttern.","Kartoffeln einschichten. Rahm und Milch mit Salz, Pfeffer und Muskat mischen, angiessen und bei 180 °C etwa 60 Minuten goldbraun backen."]},
    {"title":"Crêpes","category":"Französische Küche","description":"Dünne französische Eierpfannkuchen, süss oder herzhaft servierbar.","ingredients":[[200,"g","Mehl"],[2,"","Eier"],[300,"ml","Milch"],[30,"g","Butter, geschmolzen"],[1,"Prise","Salz"]],"steps":["Mehl, Eier, Milch, Butter und Salz zu einem glatten dünnflüssigen Teig verrühren. 20 Minuten ruhen lassen.","Eine beschichtete Pfanne dünn buttern. Teig portionsweise sehr dünn ausgiessen und Crêpes auf beiden Seiten goldgelb backen."]},
    {"title":"Französische Zwiebelsuppe","category":"Französische Küche","description":"Langsam karamellisierte Zwiebeln in kräftiger Bouillon mit Käsebrot.","ingredients":[[600,"g","Zwiebeln"],[40,"g","Butter"],[1,"l","Rinderbouillon"],[100,"ml","Weisswein"],[4,"Scheiben","Baguette"],[100,"g","Gruyère"]],"steps":["Zwiebeln in dünne Ringe schneiden und in Butter bei kleiner Hitze etwa 25 Minuten goldbraun karamellisieren. Mit Weisswein ablöschen.","Bouillon zugeben und 20 Minuten köcheln. In Schalen füllen, Baguette und Käse darauflegen und unter dem Ofengrill gratinieren."]},
    {"title":"Croque Monsieur","category":"Französische Küche","description":"Französisches überbackenes Schinken-Käse-Sandwich mit Béchamel.","ingredients":[[8,"Scheiben","Toastbrot"],[4,"Scheiben","Schinken"],[150,"g","Gruyère, gerieben"],[30,"g","Butter"],[30,"g","Mehl"],[250,"ml","Milch"]],"steps":["Butter schmelzen, Mehl einrühren und Milch nach und nach zugeben. Unter Rühren zu einer dicken Béchamelsauce kochen und würzen.","Brot mit Schinken und Käse belegen, zuklappen und mit Béchamel bestreichen. Bei 220 °C etwa 10 Minuten goldbraun überbacken."]},
    {"title":"Tarte Tatin","category":"Französische Küche","description":"Umgedrehter französischer Apfelkuchen mit karamellisierten Äpfeln.","ingredients":[[1,"","Blätterteig"],[5,"","Äpfel"],[100,"g","Zucker"],[60,"g","Butter"],[1,"TL","Zimt"]],"steps":["Zucker in einer ofenfesten Pfanne karamellisieren und Butter einrühren. Äpfel schälen, vierteln und dicht im Karamell anordnen.","Teig über die Äpfel legen und den Rand einschlagen. Bei 190 °C etwa 30 Minuten backen, kurz ruhen lassen und vorsichtig stürzen."]},
    {"title":"Wiener Schnitzel","category":"Österreichische Küche","description":"Dünnes Kalbsschnitzel mit luftiger Panade und Zitrone.","ingredients":[[4,"","Kalbsschnitzel"],[100,"g","Mehl"],[2,"","Eier"],[150,"g","Paniermehl"],[150,"g","Butterschmalz"],[1,"","Zitrone"]],"steps":["Schnitzel zwischen Folie dünn klopfen. In Mehl, verquirltem Ei und Paniermehl wenden, dabei die Panade nicht fest andrücken.","In reichlich heissem Butterschmalz schwimmend goldgelb ausbacken und dabei die Pfanne leicht schwenken. Auf Küchenpapier abtropfen lassen und mit Zitrone servieren."]},
    {"title":"Käsespätzle","category":"Österreichische Küche","description":"Alpenländische Spätzle mit geschmolzenem Käse und Röstzwiebeln.","ingredients":[[300,"g","Mehl"],[3,"","Eier"],[150,"ml","Wasser"],[200,"g","Bergkäse, gerieben"],[2,"","Zwiebeln"],[30,"g","Butter"]],"steps":["Mehl, Eier, Wasser und Salz zu einem zähen Teig schlagen. Durch ein Spätzlisieb in kochendes Salzwasser streichen und garen, bis sie aufsteigen.","Zwiebeln in Butter goldbraun rösten. Spätzle lagenweise mit Käse in eine warme Form geben, schmelzen lassen und mit Zwiebeln servieren."]},
    {"title":"Kaiserschmarrn","category":"Österreichische Küche","description":"Luftiger zerrissener Kaiserschmarrn mit Rosinen und Puderzucker.","ingredients":[[4,"","Eier"],[200,"ml","Milch"],[150,"g","Mehl"],[30,"g","Zucker"],[40,"g","Rosinen"],[30,"g","Butter"],[1,"EL","Puderzucker"]],"steps":["Eigelb mit Milch, Mehl und Zucker glatt rühren. Eiweiss steif schlagen und vorsichtig unterheben, Rosinen beigeben.","Butter in einer grossen Pfanne erhitzen, Teig hineingiessen und bei mittlerer Hitze stocken lassen. Wenden, in Stücke reissen und goldbraun fertig braten. Mit Puderzucker bestäuben."]},
    {"title":"Apfelstrudel","category":"Österreichische Küche","description":"Dünner Strudelteig mit Äpfeln, Zimt und Rosinen.","ingredients":[[1,"Packung","Strudelteig"],[5,"","Äpfel"],[50,"g","Rosinen"],[50,"g","Paniermehl"],[50,"g","Butter"],[2,"EL","Zucker"],[1,"TL","Zimt"]],"steps":["Äpfel schälen und in dünne Scheiben schneiden. Paniermehl in Butter rösten und mit Äpfeln, Rosinen, Zucker und Zimt mischen.","Füllung auf dem Strudelteig verteilen, einrollen und mit Butter bestreichen. Bei 190 °C etwa 35 Minuten goldbraun backen."]},
    {"title":"Tortilla Española","category":"Spanische Küche","description":"Spanisches Kartoffelomelett mit Zwiebeln und Eiern.","ingredients":[[600,"g","Kartoffeln"],[1,"","Zwiebel"],[6,"","Eier"],[150,"ml","Olivenöl"],[1,"TL","Salz"]],"steps":["Kartoffeln und Zwiebel in dünne Scheiben schneiden. In Olivenöl bei kleiner Hitze weich garen, ohne sie stark zu bräunen, dann abgiessen.","Eier verquirlen und mit den Kartoffeln mischen. In einer beschichteten Pfanne stocken lassen, mit Hilfe eines Tellers wenden und fertig garen."]},
    {"title":"Paella mixta","category":"Spanische Küche","description":"Spanischer Reis mit Poulet, Crevetten, Peperoni und Safran.","ingredients":[[300,"g","Rundkornreis"],[250,"g","Pouletbrust"],[200,"g","Crevetten"],[1,"","rote Peperoni"],[100,"g","Erbsen"],[800,"ml","Hühnerbouillon"],[1,"Briefchen","Safran"]],"steps":["Poulet würfeln und in einer grossen Pfanne anbraten. Peperoni und Reis zugeben und kurz mitrösten.","Safran in Bouillon lösen und angiessen. Ohne viel Rühren etwa 15 Minuten garen, Erbsen und Crevetten zugeben und fertig garen, bis der Reis die Flüssigkeit aufgenommen hat."]},
    {"title":"Gazpacho","category":"Spanische Küche","description":"Kalte andalusische Gemüsesuppe aus Tomaten, Gurke und Peperoni.","ingredients":[[800,"g","reife Tomaten"],[1,"","Gurke"],[1,"","rote Peperoni"],[1,"","Knoblauchzehe"],[2,"EL","Olivenöl"],[2,"EL","Rotweinessig"],[2,"Scheiben","Weissbrot"]],"steps":["Gemüse grob schneiden. Mit Knoblauch, Brot, Olivenöl und Essig fein pürieren.","Mit Salz und kaltem Wasser abschmecken und mindestens eine Stunde kalt stellen. Gut gekühlt servieren."]},
    {"title":"Patatas Bravas","category":"Spanische Küche","description":"Knusprige Kartoffelwürfel mit würziger spanischer Tomatensauce.","ingredients":[[800,"g","Kartoffeln"],[400,"g","gehackte Tomaten"],[1,"","Knoblauchzehe"],[1,"TL","geräuchertes Paprikapulver"],[3,"EL","Olivenöl"],[1,"Prise","Chiliflocken"]],"steps":["Kartoffeln würfeln, mit Öl und Salz mischen und bei 220 °C etwa 35 Minuten knusprig backen.","Knoblauch in wenig Öl dünsten. Tomaten, Paprika und Chili beigeben und 15 Minuten zu einer würzigen Sauce einkochen. Zu den Kartoffeln servieren."]},
    {"title":"Moussaka","category":"Griechische Küche","description":"Griechischer Auberginenauflauf mit würzigem Hackfleisch und Béchamel.","ingredients":[[2,"","Auberginen"],[400,"g","Lamm- oder Rindshackfleisch"],[400,"g","gehackte Tomaten"],[1,"","Zwiebel"],[400,"ml","Milch"],[40,"g","Butter"],[50,"g","Mehl"]],"steps":["Auberginen in Scheiben schneiden, salzen und trocken tupfen. Hackfleisch mit Zwiebel anbraten, Tomaten zugeben und 20 Minuten köcheln.","Béchamel aus Butter, Mehl und Milch kochen. Auberginen und Fleischsauce schichten, Béchamel darübergeben und bei 190 °C etwa 40 Minuten backen."]},
    {"title":"Caldo Verde","category":"Portugiesische Küche","description":"Portugiesische Kartoffelsuppe mit fein geschnittenem Kohl und Chouriço.","ingredients":[[600,"g","mehligkochende Kartoffeln"],[1,"","Zwiebel"],[1,"l","Hühnerbouillon"],[150,"g","Grünkohl oder Federkohl"],[150,"g","Chouriço"],[2,"EL","Olivenöl"]],"steps":["Kartoffeln und Zwiebel würfeln, mit Bouillon weich kochen und fein pürieren.","Kohl in sehr feine Streifen schneiden und in die Suppe geben. 10 Minuten köcheln, Chouriço in Scheiben kurz mitkochen und mit Olivenöl beträufeln."]},
    {"title":"Fish and Chips","category":"Britische Küche","description":"Knusprig ausgebackener Fisch mit dicken Pommes frites.","ingredients":[[600,"g","Kabeljaufilet"],[150,"g","Mehl"],[200,"ml","helles Bier"],[800,"g","Kartoffeln"],[1,"TL","Backpulver"],[500,"ml","Frittieröl"]],"steps":["Kartoffeln in dicke Stifte schneiden und in heissem Öl portionsweise goldgelb frittieren. Auf Küchenpapier abtropfen lassen.","Mehl, Bier und Backpulver zu einem glatten Teig rühren. Fisch portionieren, durch den Teig ziehen und goldbraun frittieren. Mit Salz und Zitronenschnitzen servieren."]},
    {"title":"Shepherd's Pie","category":"Britische Küche","description":"Britischer Hackfleisch-Gemüse-Auflauf mit Kartoffelstockkruste.","ingredients":[[500,"g","Lammhackfleisch"],[1,"","Zwiebel"],[2,"","Karotten"],[400,"ml","Rinderbouillon"],[800,"g","Kartoffeln"],[50,"g","Butter"],[100,"ml","Milch"]],"steps":["Kartoffeln weich kochen und mit Butter und Milch zu Stock zerstampfen. Hackfleisch mit Zwiebel und Karotten anbraten.","Bouillon angiessen und die Fleischmischung 15 Minuten einkochen. In eine Form geben, Kartoffelstock darauf verteilen und bei 200 °C etwa 25 Minuten backen."]},
    {"title":"Schwedische Köttbullar","category":"Schwedische Küche","description":"Schwedische Fleischbällchen mit Rahmsauce und Preiselbeeren.","ingredients":[[500,"g","Rind- und Schweinehackfleisch"],[1,"","Zwiebel"],[50,"g","Paniermehl"],[100,"ml","Milch"],[200,"ml","Rahm"],[200,"ml","Rinderbouillon"],[1,"EL","Butter"]],"steps":["Paniermehl mit Milch quellen lassen. Zwiebel fein hacken und mit Hackfleisch, Salz und Pfeffer vermengen. Kleine Bällchen formen.","Bällchen in Butter rundherum braten und warm stellen. Bouillon und Rahm in die Pfanne geben, cremig einkochen und die Bällchen darin erwärmen."]},
    {"title":"Polnische Pierogi mit Kartoffeln und Quark","category":"Polnische Küche","description":"Gefüllte Teigtaschen mit Kartoffeln, Quark und Röstzwiebeln.","ingredients":[[300,"g","Mehl"],[150,"ml","warmes Wasser"],[300,"g","Kartoffeln"],[150,"g","Quark"],[1,"","Zwiebel"],[30,"g","Butter"]],"steps":["Mehl mit Wasser und einer Prise Salz zu einem glatten Teig kneten. Kartoffeln weich kochen, zerstampfen und mit Quark mischen.","Teig dünn ausrollen, Kreise ausstechen, füllen und Ränder gut verschliessen. In Salzwasser garen, bis sie aufsteigen, und mit gebratener Zwiebel servieren."]},
    {"title":"Ungarisches Gulasch","category":"Ungarische Küche","description":"Langsam geschmortes Rindergulasch mit Zwiebeln und Paprika.","ingredients":[[800,"g","Rindsschulter in Würfeln"],[3,"","Zwiebeln"],[2,"EL","Paprikapulver edelsüss"],[2,"EL","Tomatenmark"],[700,"ml","Rinderbouillon"],[1,"","rote Peperoni"]],"steps":["Zwiebeln langsam in Öl goldgelb dünsten. Topf kurz vom Herd nehmen, Paprikapulver und Tomatenmark einrühren.","Fleisch und Bouillon zugeben und zugedeckt bei kleiner Hitze etwa 2 Stunden schmoren. Peperoni in Streifen in der letzten halben Stunde mitgaren."]},
    {"title":"Ćevapčići mit Djuvec-Reis","category":"Balkan-Küche","description":"Würzige Balkan-Hackfleischröllchen mit Paprika-Tomaten-Reis.","ingredients":[[500,"g","Rindshackfleisch"],[2,"","Knoblauchzehen"],[1,"TL","Paprikapulver"],[200,"g","Langkornreis"],[1,"","rote Peperoni"],[200,"g","gehackte Tomaten"],[500,"ml","Bouillon"]],"steps":["Hackfleisch mit gepresstem Knoblauch, Paprika, Salz und Pfeffer verkneten. Kleine längliche Röllchen formen und kalt stellen.","Reis mit Peperoni und Tomaten kurz anbraten, Bouillon angiessen und zugedeckt garen. Ćevapčići in einer heissen Pfanne rundum braten und mit dem Reis servieren."]}
  ]$recipe_data$::jsonb) loop
    if exists (
      select 1 from public.recipes
      where lower(btrim(title)) = lower(btrim(item->>'title'))
    ) then
      skipped_count := skipped_count + 1;
      continue;
    end if;

    insert into public.recipes (title, description, category)
    values (item->>'title', item->>'description', null)
    returning id into recipe_id;

    insert into public.recipe_categories (name)
    values (item->>'category')
    on conflict (name) do nothing;
    select id into category_id from public.recipe_categories where name = item->>'category';
    insert into public.recipe_category_links (recipe_id, category_id)
    values (recipe_id, category_id);

    for ingredient in select value from jsonb_array_elements(item->'ingredients') loop
      insert into public.recipe_ingredients (recipe_id, amount, unit, name)
      values (recipe_id, nullif(ingredient->>0, ''), nullif(ingredient->>1, ''), ingredient->>2);
    end loop;

    for step_row in select value, ordinality from jsonb_array_elements_text(item->'steps') with ordinality loop
      insert into public.recipe_steps (recipe_id, step_number, description)
      values (recipe_id, step_row.ordinality::integer, step_row.value);
    end loop;

    imported_count := imported_count + 1;
  end loop;
  raise notice 'Recipe import finished: % imported, % skipped.', imported_count, skipped_count;
end;
$import_recipes$;
commit;
